for id,row in pairs(additions) do
 Q.quests[id]=row.quest;D.questMeta[id]=row.meta;D.storyRows[id]=row.profile;Q.referenceMetadata[id]=row.reference
 for npc,name in pairs(row.people) do
  Q.npcs[npc]=name
  local old=D.npcQuests[npc] or "";local found=false
  for n in old:gmatch("%d+") do if tonumber(n)==id then found=true end end
  if not found then D.npcQuests[npc]=old..(old~="" and "," or "")..id end
 end
 local prior={};for _,n in ipairs(row.previous) do prior[#prior+1]=n..":P" end
